-- =============================================================================
-- ĐỒ ÁN MÔN HỌC: CÁC HỆ QUẢN TRỊ CƠ SỞ DỮ LIỆU (ORACLE 19C)
-- SCRIPT 01: KHỞI TẠO CẤU TRÚC BẢNG (DDL), VIEW VÀ INDEX
-- Hệ thống: Nhà thuốc trực tuyến Long Châu
-- =============================================================================

-- 1. Bảng Categories (Danh mục sản phẩm)
CREATE TABLE "Categories" (
    "CategoryId" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "CategoryName" NVARCHAR2(256) NOT NULL,
    "Description" NVARCHAR2(1000),
    "ImageUrl" VARCHAR2(512),
    "ParentCategoryId" NUMBER(10),
    "IsFeature" NUMBER(1) DEFAULT 0 NOT NULL,
    "CategoryLevel" VARCHAR2(50),
    "ProductCount" NUMBER(10) DEFAULT 0 NOT NULL,
    CONSTRAINT "PK_Categories" PRIMARY KEY ("CategoryId"),
    CONSTRAINT "FK_Categories_Parent" FOREIGN KEY ("ParentCategoryId") 
        REFERENCES "Categories" ("CategoryId") ON DELETE SET NULL,
    CONSTRAINT "CK_Categories_Feature" CHECK ("IsFeature" IN (0, 1))
);

-- 2. Bảng Suppliers (Nhà cung cấp)
CREATE TABLE "Suppliers" (
    "SupplierId" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "Code" VARCHAR2(50) NOT NULL,
    "Name" NVARCHAR2(256) NOT NULL,
    "Phone" VARCHAR2(20),
    "Email" VARCHAR2(100),
    "Address" NVARCHAR2(500),
    "TaxCode" VARCHAR2(50),
    "IsActive" NUMBER(1) DEFAULT 1 NOT NULL,
    CONSTRAINT "PK_Suppliers" PRIMARY KEY ("SupplierId"),
    CONSTRAINT "UQ_Suppliers_Code" UNIQUE ("Code"),
    CONSTRAINT "CK_Suppliers_Active" CHECK ("IsActive" IN (0, 1))
);

-- 3. Bảng Products (Sản phẩm / Dược phẩm)
CREATE TABLE "Products" (
    "ProductId" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "ProductName" NVARCHAR2(256) NOT NULL,
    "Sku" VARCHAR2(100),
    "Barcode" VARCHAR2(100),
    "RegistrationNumber" VARCHAR2(100),
    "RequiresPrescription" NUMBER(1) DEFAULT 0 NOT NULL,
    "CostPrice" NUMBER(18, 2) DEFAULT 0 NOT NULL,
    "Price" NUMBER(18, 2) DEFAULT 0 NOT NULL,
    "Brand" NVARCHAR2(100),
    "Package" NVARCHAR2(100),
    "CategoryId" NUMBER(10),
    "SupplierId" NUMBER(10),
    "Ingredients" NVARCHAR2(1000),
    "Uses" NVARCHAR2(2000),
    "Dosage" NVARCHAR2(2000),
    "Contraindications" NVARCHAR2(2000),
    "IngredientUnit" NVARCHAR2(50),
    "IsFeature" NUMBER(1) DEFAULT 0 NOT NULL,
    "Origin" NVARCHAR2(100),
    "StockQuantity" NUMBER(10) DEFAULT 0 NOT NULL,
    "MinStockLevel" NUMBER(10) DEFAULT 0 NOT NULL,
    "IsActive" NUMBER(1) DEFAULT 1 NOT NULL,
    "Slug" VARCHAR2(256),
    "SoldQuantity" NUMBER(10) DEFAULT 0,
    CONSTRAINT "PK_Products" PRIMARY KEY ("ProductId"),
    CONSTRAINT "FK_Products_Category" FOREIGN KEY ("CategoryId") 
        REFERENCES "Categories" ("CategoryId") ON DELETE SET NULL,
    CONSTRAINT "FK_Products_Supplier" FOREIGN KEY ("SupplierId") 
        REFERENCES "Suppliers" ("SupplierId") ON DELETE SET NULL,
    CONSTRAINT "CK_Products_Price" CHECK ("Price" >= 0),
    CONSTRAINT "CK_Products_CostPrice" CHECK ("CostPrice" >= 0),
    CONSTRAINT "CK_Products_StockQty" CHECK ("StockQuantity" >= 0),
    CONSTRAINT "CK_Products_Prescription" CHECK ("RequiresPrescription" IN (0, 1)),
    CONSTRAINT "CK_Products_Active" CHECK ("IsActive" IN (0, 1))
);

-- 4. Bảng ProductImages (Hình ảnh sản phẩm)
CREATE TABLE "ProductImages" (
    "ProductImageId" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "ProductId" NUMBER(10) NOT NULL,
    "ImageUrl" VARCHAR2(512) NOT NULL,
    "SortOrder" NUMBER(10) DEFAULT 0,
    "IsMain" NUMBER(1) DEFAULT 0,
    CONSTRAINT "PK_ProductImages" PRIMARY KEY ("ProductImageId"),
    CONSTRAINT "FK_ProductImages_Product" FOREIGN KEY ("ProductId") 
        REFERENCES "Products" ("ProductId") ON DELETE CASCADE,
    CONSTRAINT "CK_ProductImages_Main" CHECK ("IsMain" IN (0, 1))
);

-- 5. Bảng AspNetUsers (Tài khoản người dùng)
CREATE TABLE "AspNetUsers" (
    "Id" VARCHAR2(450) NOT NULL,
    "UserName" NVARCHAR2(256) NOT NULL,
    "Email" VARCHAR2(256),
    "PasswordHash" VARCHAR2(1000),
    "PhoneNumber" VARCHAR2(50),
    "FullName" NVARCHAR2(256),
    "Address" NVARCHAR2(500),
    CONSTRAINT "PK_AspNetUsers" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_AspNetUsers_UserName" UNIQUE ("UserName")
);

-- 6. Bảng UserRankInfos (Thông tin xếp hạng khách hàng thân thiết)
CREATE TABLE "UserRankInfos" (
    "UserId" VARCHAR2(450) NOT NULL,
    "TotalSpent" NUMBER(18, 2) DEFAULT 0 NOT NULL,
    "TotalSpent6Months" NUMBER(18, 2) DEFAULT 0 NOT NULL,
    "Rank" VARCHAR2(50) DEFAULT 'Bạc' NOT NULL,
    "LoyaltyPoints" NUMBER(10) DEFAULT 0 NOT NULL,
    CONSTRAINT "PK_UserRankInfos" PRIMARY KEY ("UserId"),
    CONSTRAINT "FK_UserRankInfos_User" FOREIGN KEY ("UserId") 
        REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE,
    CONSTRAINT "CK_UserRankInfos_Rank" CHECK ("Rank" IN ('Bạc', 'Vàng', 'Bạch kim')),
    CONSTRAINT "CK_UserRankInfos_Points" CHECK ("LoyaltyPoints" >= 0)
);

-- 7. Bảng Vouchers (Mã giảm giá)
CREATE TABLE "Vouchers" (
    "VoucherId" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "Code" VARCHAR2(100) NOT NULL,
    "Description" NVARCHAR2(500),
    "ExpiryDate" DATE NOT NULL,
    "DiscountAmount" NUMBER(18, 2) DEFAULT 0,
    "PercentValue" NUMBER(5, 2) DEFAULT 0,
    "DiscountType" VARCHAR2(50) DEFAULT 'FullOrder' NOT NULL,
    "MinOrderAmount" NUMBER(18, 2) DEFAULT 0,
    "RequiredRank" VARCHAR2(50),
    "MaxUsage" NUMBER(10),
    "UsedCount" NUMBER(10) DEFAULT 0 NOT NULL,
    "IsPublic" NUMBER(1) DEFAULT 1 NOT NULL,
    "IsActive" NUMBER(1) DEFAULT 1 NOT NULL,
    "CategoryId" NUMBER(10),
    CONSTRAINT "PK_Vouchers" PRIMARY KEY ("VoucherId"),
    CONSTRAINT "UQ_Vouchers_Code" UNIQUE ("Code"),
    CONSTRAINT "FK_Vouchers_Category" FOREIGN KEY ("CategoryId") 
        REFERENCES "Categories" ("CategoryId") ON DELETE SET NULL,
    CONSTRAINT "CK_Vouchers_Active" CHECK ("IsActive" IN (0, 1)),
    CONSTRAINT "CK_Vouchers_Public" CHECK ("IsPublic" IN (0, 1))
);

-- 8. Bảng UserVouchers (Sở hữu Voucher người dùng)
CREATE TABLE "UserVouchers" (
    "UserVoucherId" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "UserId" VARCHAR2(450) NOT NULL,
    "VoucherId" NUMBER(10) NOT NULL,
    "IsUsed" NUMBER(1) DEFAULT 0 NOT NULL,
    "UsedDate" DATE,
    CONSTRAINT "PK_UserVouchers" PRIMARY KEY ("UserVoucherId"),
    CONSTRAINT "FK_UserVouchers_User" FOREIGN KEY ("UserId") 
        REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_UserVouchers_Voucher" FOREIGN KEY ("VoucherId") 
        REFERENCES "Vouchers" ("VoucherId") ON DELETE CASCADE,
    CONSTRAINT "UQ_UserVouchers" UNIQUE ("UserId", "VoucherId"),
    CONSTRAINT "CK_UserVouchers_Used" CHECK ("IsUsed" IN (0, 1))
);

-- 9. Bảng Warehouses (Kho hàng)
CREATE TABLE "Warehouses" (
    "WarehouseId" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "Name" NVARCHAR2(256) NOT NULL,
    "Address" NVARCHAR2(500),
    "IsDefault" NUMBER(1) DEFAULT 0 NOT NULL,
    "IsActive" NUMBER(1) DEFAULT 1 NOT NULL,
    CONSTRAINT "PK_Warehouses" PRIMARY KEY ("WarehouseId"),
    CONSTRAINT "CK_Warehouses_Default" CHECK ("IsDefault" IN (0, 1)),
    CONSTRAINT "CK_Warehouses_Active" CHECK ("IsActive" IN (0, 1))
);

-- 10. Bảng WarehouseStocks (Tồn kho theo kho)
CREATE TABLE "WarehouseStocks" (
    "WarehouseStockId" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "WarehouseId" NUMBER(10) NOT NULL,
    "ProductId" NUMBER(10) NOT NULL,
    "QuantityOnHand" NUMBER(10) DEFAULT 0 NOT NULL,
    "QuantityReserved" NUMBER(10) DEFAULT 0 NOT NULL,
    CONSTRAINT "PK_WarehouseStocks" PRIMARY KEY ("WarehouseStockId"),
    CONSTRAINT "FK_WHStocks_Warehouse" FOREIGN KEY ("WarehouseId") 
        REFERENCES "Warehouses" ("WarehouseId"),
    CONSTRAINT "FK_WHStocks_Product" FOREIGN KEY ("ProductId") 
        REFERENCES "Products" ("ProductId"),
    CONSTRAINT "UQ_Warehouse_Product" UNIQUE ("WarehouseId", "ProductId"),
    CONSTRAINT "CK_WHStocks_QtyOnHand" CHECK ("QuantityOnHand" >= 0),
    CONSTRAINT "CK_WHStocks_QtyReserved" CHECK ("QuantityReserved" >= 0)
);

-- 11. Bảng ProductBatches (Lô thuốc quản lý theo HSD)
CREATE TABLE "ProductBatches" (
    "ProductBatchId" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "ProductId" NUMBER(10) NOT NULL,
    "WarehouseId" NUMBER(10) NOT NULL,
    "BatchNo" VARCHAR2(100) NOT NULL,
    "ExpiryDate" DATE NOT NULL,
    "QuantityOnHand" NUMBER(10) DEFAULT 0 NOT NULL,
    "UnitCost" NUMBER(18, 2) DEFAULT 0 NOT NULL,
    CONSTRAINT "PK_ProductBatches" PRIMARY KEY ("ProductBatchId"),
    CONSTRAINT "FK_Batches_Product" FOREIGN KEY ("ProductId") 
        REFERENCES "Products" ("ProductId"),
    CONSTRAINT "FK_Batches_Warehouse" FOREIGN KEY ("WarehouseId") 
        REFERENCES "Warehouses" ("WarehouseId"),
    CONSTRAINT "CK_Batches_Qty" CHECK ("QuantityOnHand" >= 0),
    CONSTRAINT "CK_Batches_UnitCost" CHECK ("UnitCost" >= 0)
);

-- 12. Bảng Orders (Đơn hàng)
CREATE TABLE "Orders" (
    "OrderId" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "UserId" VARCHAR2(450),
    "OrderDate" DATE DEFAULT SYSDATE NOT NULL,
    "TotalAmount" NUMBER(18, 2) DEFAULT 0 NOT NULL,
    "Status" NVARCHAR2(50) DEFAULT 'Chờ xác nhận' NOT NULL,
    "ShippingAddress" NVARCHAR2(500),
    "PaymentStatus" NVARCHAR2(50) DEFAULT 'Chưa thanh toán' NOT NULL,
    "FullName" NVARCHAR2(256),
    "Phone" VARCHAR2(50),
    "VoucherCode" VARCHAR2(100),
    "VoucherDiscount" NUMBER(18, 2) DEFAULT 0,
    "PrescriptionNote" NVARCHAR2(1000),
    CONSTRAINT "PK_Orders" PRIMARY KEY ("OrderId"),
    CONSTRAINT "FK_Orders_User" FOREIGN KEY ("UserId") 
        REFERENCES "AspNetUsers" ("Id") ON DELETE SET NULL,
    CONSTRAINT "CK_Orders_Total" CHECK ("TotalAmount" >= 0),
    CONSTRAINT "CK_Orders_Status" CHECK ("Status" IN ('Chờ thanh toán', 'Chờ xác nhận', 'Đã xác nhận', 'Đang đóng gói', 'Đang giao', 'Đã giao', 'Đã hủy'))
);

-- 13. Bảng OrderItems (Chi tiết đơn hàng)
CREATE TABLE "OrderItems" (
    "OrderItemId" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "OrderId" NUMBER(10) NOT NULL,
    "ProductId" NUMBER(10) NOT NULL,
    "Quantity" NUMBER(10) NOT NULL,
    "Price" NUMBER(18, 2) NOT NULL,
    CONSTRAINT "PK_OrderItems" PRIMARY KEY ("OrderItemId"),
    CONSTRAINT "FK_OrderItems_Order" FOREIGN KEY ("OrderId") 
        REFERENCES "Orders" ("OrderId") ON DELETE CASCADE,
    CONSTRAINT "FK_OrderItems_Product" FOREIGN KEY ("ProductId") 
        REFERENCES "Products" ("ProductId"),
    CONSTRAINT "CK_OrderItems_Qty" CHECK ("Quantity" > 0),
    CONSTRAINT "CK_OrderItems_Price" CHECK ("Price" >= 0)
);

-- 14. Bảng Payments (Thanh toán)
CREATE TABLE "Payments" (
    "PaymentId" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "OrderId" NUMBER(10),
    "PaymentMethod" VARCHAR2(50) NOT NULL,
    "Amount" NUMBER(18, 2) DEFAULT 0 NOT NULL,
    "PaymentDate" DATE,
    "PaymentStatus" VARCHAR2(50) DEFAULT 'Pending' NOT NULL,
    "TransactionId" VARCHAR2(100),
    CONSTRAINT "PK_Payments" PRIMARY KEY ("PaymentId"),
    CONSTRAINT "FK_Payments_Order" FOREIGN KEY ("OrderId") 
        REFERENCES "Orders" ("OrderId") ON DELETE SET NULL,
    CONSTRAINT "CK_Payments_Amount" CHECK ("Amount" >= 0)
);

-- 15. Bảng VoucherRedemptions (Lịch sử sử dụng Voucher)
CREATE TABLE "VoucherRedemptions" (
    "VoucherRedemptionId" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "VoucherId" NUMBER(10) NOT NULL,
    "UserId" VARCHAR2(450) NOT NULL,
    "OrderId" NUMBER(10) NOT NULL,
    "DiscountAmount" NUMBER(18, 2) NOT NULL,
    "RedeemedAt" DATE DEFAULT SYSDATE NOT NULL,
    "IsReverted" NUMBER(1) DEFAULT 0 NOT NULL,
    CONSTRAINT "PK_VoucherRedemptions" PRIMARY KEY ("VoucherRedemptionId"),
    CONSTRAINT "FK_VRedemp_Voucher" FOREIGN KEY ("VoucherId") 
        REFERENCES "Vouchers" ("VoucherId"),
    CONSTRAINT "FK_VRedemp_Order" FOREIGN KEY ("OrderId") 
        REFERENCES "Orders" ("OrderId"),
    CONSTRAINT "UQ_VoucherRedemp" UNIQUE ("VoucherId", "OrderId"),
    CONSTRAINT "CK_VRedemp_Reverted" CHECK ("IsReverted" IN (0, 1))
);

-- 16. Bảng InventoryTransactions (Nhật ký giao dịch kho)
CREATE TABLE "InventoryTransactions" (
    "TransactionId" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "ProductId" NUMBER(10) NOT NULL,
    "WarehouseId" NUMBER(10) NOT NULL,
    "TransactionType" VARCHAR2(50) NOT NULL,
    "Quantity" NUMBER(10) NOT NULL,
    "QuantityBefore" NUMBER(10) NOT NULL,
    "QuantityAfter" NUMBER(10) NOT NULL,
    "OrderId" NUMBER(10),
    "TransactionDate" DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT "PK_InventoryTransactions" PRIMARY KEY ("TransactionId"),
    CONSTRAINT "FK_InvTrans_Product" FOREIGN KEY ("ProductId") 
        REFERENCES "Products" ("ProductId"),
    CONSTRAINT "FK_InvTrans_Warehouse" FOREIGN KEY ("WarehouseId") 
        REFERENCES "Warehouses" ("WarehouseId"),
    CONSTRAINT "CK_InvTrans_Type" CHECK ("TransactionType" IN ('Import', 'Sale', 'Return', 'BatchSale', 'Adjustment'))
);

-- 17. Bảng DbActivityLogs (Nhật ký hoạt động hệ thống)
CREATE TABLE "DbActivityLogs" (
    "Id" NUMBER(10) GENERATED BY DEFAULT AS IDENTITY,
    "UserId" VARCHAR2(450),
    "UserEmail" NVARCHAR2(256),
    "Action" NVARCHAR2(100) NOT NULL,
    "EntityName" VARCHAR2(100) NOT NULL,
    "EntityId" VARCHAR2(100),
    "Description" NCLOB,
    "CreatedAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "PK_DbActivityLogs" PRIMARY KEY ("Id")
);

-- =============================================================================
-- KHỞI TẠO VIEWS & INDEXES
-- =============================================================================

-- View 1: Danh mục sản phẩm kèm tồn kho
CREATE OR REPLACE VIEW V_ProductCatalog AS
SELECT 
    p."ProductId",
    p."ProductName",
    p."Sku",
    p."Price",
    c."CategoryName",
    p."StockQuantity",
    p."RequiresPrescription"
FROM "Products" p
LEFT JOIN "Categories" c ON p."CategoryId" = c."CategoryId"
WHERE p."IsActive" = 1;
/

-- View 2: Báo cáo doanh số theo tháng của năm hiện tại
CREATE OR REPLACE VIEW V_MonthlyRevenue AS
SELECT 
    TO_CHAR(o."OrderDate", 'MM') AS SalesMonth,
    COUNT(o."OrderId") AS TotalOrders,
    SUM(o."TotalAmount") AS TotalRevenue,
    SUM(o."VoucherDiscount") AS TotalDiscountApplied
FROM "Orders" o
WHERE o."Status" = 'Đã giao' AND TO_CHAR(o."OrderDate", 'YYYY') = TO_CHAR(SYSDATE, 'YYYY')
GROUP BY TO_CHAR(o."OrderDate", 'MM');
/

-- Index 1: Tìm kiếm nhanh sản phẩm theo tên thương mại (không phân biệt hoa thường)
CREATE INDEX IDX_Products_Name ON "Products" (UPPER("ProductName"));
/

-- Index 2: Tăng tốc tra cứu đơn hàng theo thời gian đặt hàng
CREATE INDEX IDX_Orders_OrderDate ON "Orders" ("OrderDate");
/

-- Index 3: Tăng tốc kiểm tra HSD của lô thuốc cận date
CREATE INDEX IDX_Batches_ExpiryDate ON "ProductBatches" ("ExpiryDate");
/
